def count_array_restorations(s, k):
 mod=1000000007;n=len(s);ways=[0]*(n+1);ways[n]=1
 for i in range(n-1,-1,-1):
  if s[i]=='0':continue
  value=0
  for j in range(i,n):
   value=value*10+int(s[j])
   if value>k:break
   ways[i]=(ways[i]+ways[j+1])%mod
 return ways[0]

